import { integer, pgEnum, timestamp, uuid } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";

/** Who performed a write. Derived from the auth method (Bearer = agent, cookie = user). */
export const actorEnum = pgEnum("actor", ["agent", "user", "system"]);

/** Primary key: UUIDv7 generated by Postgres 18; the app may also supply one (offline creates). */
export const id = () =>
  uuid()
    .primaryKey()
    .default(sql`uuidv7()`);

export const createdAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();

export const updatedAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();

/**
 * Columns shared by every mutable row. `updated_at` and `version` are maintained by the
 * `bump_row_version` trigger (see the custom migration), so no write path can forget them.
 */
export const mutable = () => ({
  createdAt: createdAt(),
  updatedAt: updatedAt(),
  version: integer().notNull().default(1),
  updatedBy: actorEnum().notNull(),
});

/** Matches local `HH:mm` (00:00–23:59). */
export const HHMM_REGEX = "^([01][0-9]|2[0-3]):[0-5][0-9]$";
